/** Fill the holes of a 2-D cell set (cells not reachable from outside its bounding box). */
function fillHoles(set, X, Z) {
  const seen = new Set(), q = [];
  for (let x = -1; x <= X; x++) q.push([x, -1], [x, Z]);
  for (let z = -1; z <= Z; z++) q.push([-1, z], [X, z]);
  for (const p of q) seen.add(K(...p));
  while (q.length) {
    const [x, z] = q.pop();
    for (const [dx, dz] of Object.values(DIR)) {
      const nx = x + dx, nz = z + dz, k = K(nx, nz);
      if (nx < -1 || nz < -1 || nx > X || nz > Z || seen.has(k) || set.has(k)) continue;
      seen.add(k); q.push([nx, nz]);
    }
  }
  const out = new Set();
  for (let x = 0; x < X; x++) for (let z = 0; z < Z; z++) if (!seen.has(K(x, z))) out.add(K(x, z));
  return out;
}

