export const IMPLUVIUM_COLUMNS = [[14, 13], [21, 13], [14, 18], [21, 18]];
/** Garden court: open sky x11..24, z35..41. Fountain basin x15..20, z36..40. */
export const GARDEN_COURT = { x0: 11, z0: 35, x1: 24, z1: 41 };
