expectBlock(17, 1, 2, V.STONE_BRICKS);            // the plinth is always built
expectBlock(17, 6, 2, V.CUT_SANDSTONE);           // the cornice is always built
ok(throws(() => V.wallLine(g, 0, 2, 5, 9)), "wallLine accepted a diagonal wall");

ran.add("pilaster");
