// Writes one STUB module per part: its scope (from scopes.json) and its plan.md entry (PARTS line for P1..P6, ROOMS row for rooms).
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const dir = process.argv[2];
const plan = readFileSync(join(dir, "plan.md"), "utf8").split("\n");
const scopes = JSON.parse(readFileSync("/tmp/gen/scopes.json", "utf8"));

const partsLines = plan.filter((l) => /^\d\. P\d `parts\/\w+\.mjs`/.test(l));
const roomsStart = plan.indexOf("## ROOMS"), roomsEnd = plan.indexOf("## OPENINGS");
const roomRows = plan.slice(roomsStart, roomsEnd).filter((l) => l.startsWith("| ") && !l.startsWith("| room") && !l.startsWith("|---"));
if (partsLines.length !== 6 || roomRows.length !== 18 || scopes.length !== 24) {
  throw new Error(`counts: parts ${partsLines.length}, rooms ${roomRows.length}, scopes ${scopes.length}`);
}

const planEntryFor = (module) => {
  const p = partsLines.find((l) => l.includes("`" + module + "`"));
  if (p) return { label: "plan.md PARTS entry:", text: p };
  const m = module.match(/^parts\/room-(\d+)\.mjs$/);
  if (!m) throw new Error(`no plan entry for ${module}`);
  return { label: "plan.md ROOMS row:", text: roomRows[Number(m[1]) - 1] };
};

/** Greedy word wrap that keeps every word exactly as written. */
const wrap = (text, width = 112) => {
  const out = [];
  let line = "";
  for (const word of text.split(" ")) {
    if (line && (line + " " + word).length > width) { out.push(line); line = word; }
    else line = line ? line + " " + word : word;
  }
  if (line) out.push(line);
  return out.map((l) => "// " + l);
};

for (const { module, scope } of scopes) {
  const entry = planEntryFor(module);
  const body = [
    "// STUB: build(g) does nothing yet. The part's worker replaces this file.",
    "//",
    "// Scope:",
    ...wrap(scope, 112).map((l) => "//   " + l.slice(3)),
    "//",
    `// ${entry.label}`,
    ...wrap(entry.text, 112).map((l) => "//   " + l.slice(3)),
    "export function build(g) {}",
    "",
  ];
  const path = join(dir, module);
  mkdirSync(join(dir, "parts"), { recursive: true });
  writeFileSync(path, body.join("\n"));
}
console.log(`wrote ${scopes.length} stubs under ${join(dir, "parts")}`);

